from __future__ import annotations

import json
import os
from typing import Any

from mcp import ClientSession
from mcp.client.streamable_http import streamablehttp_client

from lfx.custom import Component
from lfx.io import IntInput, MessageInput, MultilineInput, Output
from lfx.schema import Data
from lfx.schema.message import Message
from lfx.utils.secrets import unwrap_secret_value


def _decode_tool_result(result: Any) -> dict[str, Any]:
    if bool(
        getattr(result, "isError", False)
        or getattr(result, "is_error", False)
    ):
        detail = " ".join(
            str(getattr(item, "text", "") or "").strip()
            for item in getattr(result, "content", []) or []
            if str(getattr(item, "text", "") or "").strip()
        )
        raise RuntimeError(detail or "BoI Wiki MCP tool call failed")
    structured = getattr(result, "structuredContent", None) or getattr(result, "structured_content", None)
    if isinstance(structured, dict):
        return structured
    for item in getattr(result, "content", []) or []:
        text = getattr(item, "text", "")
        if not text:
            continue
        try:
            decoded = json.loads(text)
        except json.JSONDecodeError:
            continue
        if isinstance(decoded, dict):
            return decoded
    return {}


class BoIWikiKnowledge(Component):
    display_name = "Wiki에서 지식 가져오기"
    description = "Task·SOP 맥락을 자동 판별하고 ACL 내 Wiki 문서와 검증된 Ontology 관계를 함께 가져옵니다."
    icon = "book-open"
    name = "BoIWikiKnowledge"

    inputs = [
        MessageInput(name="question", display_name="질문", required=True),
        MultilineInput(name="business_context", display_name="업무 맥락", required=False),
        IntInput(name="limit", display_name="검색 개수", value=6, advanced=True),
    ]
    outputs = [
        Output(name="knowledge", display_name="근거가 포함된 지식", method="load_knowledge"),
        Output(name="agent_context", display_name="Agent 문맥", method="build_agent_context"),
    ]

    def _request_variables(self) -> dict[str, Any]:
        try:
            graph = getattr(self, "graph", None)
            context = getattr(graph, "context", {}) if graph else {}
            request_variables = context.get("request_variables") if isinstance(context, dict) else {}
        except Exception:
            request_variables = {}
        return request_variables if isinstance(request_variables, dict) else {}

    async def _credential(self) -> str:
        run_token = str(self._request_variables().get("BOI_RUN_TOKEN") or "").strip()
        if run_token:
            return run_token
        try:
            value = await self.get_variables("BOI_WIKI_PAT", "value")
        except (TypeError, ValueError):
            value = ""
        raw_value = unwrap_secret_value(value)
        if str(raw_value or "").strip():
            return str(raw_value).strip()
        raise ValueError("BoI 지식 연결이 없습니다. Agent Playground 온보딩을 먼저 완료하세요.")

    async def _mcp_headers(self) -> dict[str, str]:
        headers = {"Authorization": f"Bearer {await self._credential()}"}
        variables = self._request_variables()
        for variable, header in {
            "BOI_ACTION_KEY": "X-BOI-Action-Key",
            "BOI_DEPLOYMENT_ID": "X-BOI-Deployment-ID",
            "BOI_ENDPOINT_ID": "X-BOI-Endpoint-ID",
            "BOI_PROJECT_ID": "X-BOI-Project-ID",
            "BOI_FLOW_ID": "X-BOI-Flow-ID",
            "BOI_TRACE_ID": "X-BOI-Trace-ID",
            "BOI_EXECUTION_ID": "X-BOI-Execution-ID",
        }.items():
            value = str(variables.get(variable) or "").strip()
            if value:
                headers[header] = value
        return headers

    def _request_payload(self) -> dict[str, Any]:
        value = self.question
        if hasattr(value, "text"):
            value = value.text
        text = str(value or "").strip()
        if not text:
            return {}
        try:
            decoded = json.loads(text)
        except json.JSONDecodeError:
            return {"question": text}
        if not isinstance(decoded, dict):
            return {"question": text}
        return decoded

    @staticmethod
    def _profile(request: dict[str, Any], business_context: str) -> str:
        task_ref = str(request.get("task_ref") or "").strip()
        page_ref = str(request.get("page_ref") or "").strip()
        explicit_sop = any(
            str(request.get(key) or "").strip()
            for key in ("sop_ref", "sop_stage", "stage_ref", "event_ref", "action_ref")
        )
        if task_ref and explicit_sop:
            return "sop_task_execution"
        if task_ref:
            return "task_execution"
        if page_ref or str(request.get("context_id") or "").strip():
            return "wiki_context"
        return "knowledge_lookup"

    @staticmethod
    def _grounded_edges(graph: dict[str, Any], *, view: str, seed: str) -> list[dict[str, Any]]:
        grounded: list[dict[str, Any]] = []
        for edge in graph.get("edges") or []:
            if not isinstance(edge, dict):
                continue
            payload = edge.get("payload") if isinstance(edge.get("payload"), dict) else {}
            provenance = str(payload.get("provenance") or "")
            metadata = payload.get("metadata") if isinstance(payload.get("metadata"), dict) else {}
            source_refs = [
                str(item)
                for item in payload.get("source_refs") or []
                if str(item).strip()
            ]
            if metadata.get("source_ref"):
                source_refs.append(str(metadata["source_ref"]))
            source_refs = list(dict.fromkeys(source_refs))
            if provenance in {"", "inferred", "ambiguous"} or not source_refs:
                continue
            grounded.append(
                {
                    "edge_id": str(edge.get("edge_id") or ""),
                    "source_id": str(edge.get("source_id") or ""),
                    "target_id": str(edge.get("target_id") or ""),
                    "relation": str(edge.get("user_label") or payload.get("user_label") or edge.get("relation") or ""),
                    "provenance": provenance,
                    "source_refs": source_refs,
                    "view": view,
                    "seed": seed,
                }
            )
        return grounded

    async def _payload(self) -> dict[str, Any]:
        request = self._request_payload()
        cache_key = json.dumps(request, ensure_ascii=False, sort_keys=True, default=str)
        if (
            getattr(self, "_boi_payload_cache_key", "") == cache_key
            and isinstance(getattr(self, "_boi_payload_cache", None), dict)
        ):
            return dict(self._boi_payload_cache)
        question = str(request.get("question") or "").strip()
        if not question:
            raise ValueError("질문이 필요합니다.")
        business_context = str(request.get("business_context") or self.business_context or "").strip()
        task_anchor = (
            request.get("task_anchor")
            if isinstance(request.get("task_anchor"), dict)
            else {}
        )
        task_ref = str(
            task_anchor.get("task_id")
            or request.get("task_ref")
            or ""
        ).strip()
        page_ref = str(request.get("page_ref") or "").strip()
        context_id = str(request.get("context_id") or "").strip()
        profile = self._profile(request, business_context)
        endpoint = os.getenv("BOI_WIKI_MCP_URL", "http://boi-wiki-mcp:8200/mcp/v2")
        graph_results: list[dict[str, Any]] = []
        graph_errors: list[dict[str, str]] = []
        details: list[dict[str, Any]] = []
        context_pack: dict[str, Any] = {}
        async with streamablehttp_client(
            endpoint,
            headers=await self._mcp_headers(),
        ) as (read_stream, write_stream, _):
            async with ClientSession(read_stream, write_stream) as session:
                await session.initialize()

                async def call(tool_name: str, arguments: dict[str, Any]) -> dict[str, Any]:
                    return _decode_tool_result(await session.call_tool(tool_name, arguments))

                search = await call(
                    "boi_search",
                    {
                        "query": question,
                        "include_history": True,
                        "include_drafts": False,
                        "limit": max(1, min(int(self.limit or 6), 12)),
                        "page_ref": page_ref,
                        "task_ref": task_ref,
                        "trace_id": str(
                            task_anchor.get("trace_id")
                            or request.get("trace_id")
                            or ""
                        ),
                        "event_id": str(
                            task_anchor.get("event_id")
                            or request.get("event_id")
                            or ""
                        ),
                        "action_key": str(
                            task_anchor.get("action_key")
                            or request.get("action_ref")
                            or ""
                        ),
                        "view": "ranked",
                    },
                )
                context_pack = (
                    search.get("context_pack")
                    if isinstance(search.get("context_pack"), dict)
                    else {}
                )
                profile = str(
                    context_pack.get("context_profile")
                    or search.get("context_profile")
                    or profile
                )
                items = [item for item in search.get("items") or [] if isinstance(item, dict)]
                resolved_task_seed = str(
                    (
                        context_pack.get("task")
                        if isinstance(context_pack.get("task"), dict)
                        else {}
                    ).get("task_id")
                    or task_ref
                ).strip()
                seeds = list(
                    dict.fromkeys(
                        [
                            *([resolved_task_seed] if resolved_task_seed else []),
                            *(
                                [str(request.get("sop_ref") or "").strip()]
                                if str(request.get("sop_ref") or "").strip()
                                else []
                            ),
                            *([page_ref] if page_ref else []),
                            *[
                                str(item.get("evidence_id") or item.get("ref") or "")
                                for item in items
                                if str(item.get("evidence_id") or item.get("ref") or "")
                            ],
                        ]
                    )
                )[:3]
                views = {
                    "sop_task_execution": ["workflow", "responsibility", "lineage", "impact"],
                    "task_execution": ["responsibility", "lineage", "impact"],
                    "wiki_context": ["neighbors", "lineage"],
                    "knowledge_lookup": ["neighbors"],
                }[profile]
                for seed_index, seed in enumerate(seeds):
                    selected_views = views if seed_index == 0 else views[:1]
                    for view in selected_views:
                        try:
                            graph = await call(
                                "boi_search",
                                {
                                    "query": question,
                                    "view": view,
                                    "source_ref": seed,
                                    "depth": 2,
                                    "limit": 40,
                                },
                            )
                            graph_results.append({"seed": seed, "view": view, **graph})
                        except Exception as exc:
                            graph_errors.append({"seed": seed, "view": view, "reason": type(exc).__name__})
                for item in items[:4]:
                    ref = str(item.get("evidence_id") or item.get("ref") or "").strip()
                    if not ref:
                        continue
                    try:
                        details.append(await call("boi_get", {"ref": ref}))
                    except Exception:
                        continue
        source_references = [
            {
                "ref": str(item.get("evidence_id") or item.get("ref") or ""),
                "title": str(item.get("title") or ""),
                "url": str(item.get("url") or ""),
                "source": str(item.get("source") or item.get("authority") or ""),
            }
            for item in items
        ]
        ontology_relationships: list[dict[str, Any]] = []
        for graph in graph_results:
            ontology_relationships.extend(
                self._grounded_edges(
                    graph,
                    view=str(graph.get("view") or ""),
                    seed=str(graph.get("seed") or ""),
                )
            )
        ontology_relationships = list(
            {
                (
                    item["source_id"],
                    item["relation"],
                    item["target_id"],
                    tuple(item["source_refs"]),
                ): item
                for item in ontology_relationships
            }.values()
        )[:40]
        denied_count = int(search.get("excluded_count") or search.get("permission_excluded_count") or 0)
        if items and ontology_relationships:
            grounding_status = "grounded_with_ontology"
        elif items:
            grounding_status = "grounded_document_fallback"
        elif ontology_relationships:
            grounding_status = "grounded_ontology_only"
        else:
            grounding_status = "no_accessible_evidence"
        resolved_task = (
            context_pack.get("task")
            if isinstance(context_pack.get("task"), dict)
            else {}
        )
        resolved_stage = (
            context_pack.get("sop_stage")
            if isinstance(context_pack.get("sop_stage"), dict)
            else {}
        )
        trace_context = (
            context_pack.get("trace_context")
            if isinstance(context_pack.get("trace_context"), dict)
            else {}
        )
        trace_events = [
            item
            for item in trace_context.get("events") or []
            if isinstance(item, dict)
        ]
        task_context = {
            "profile": profile,
            "task_ref": task_ref or str(resolved_task.get("task_id") or ""),
            "resolved_task_id": str(resolved_task.get("task_id") or ""),
            "page_ref": page_ref,
            "context_id": str(context_pack.get("context_id") or context_id),
            "sop_ref": str(resolved_stage.get("sop_ref") or ""),
            "sop_stage": str(resolved_stage.get("sop_stage_id") or ""),
            "workflow_definition_key": str(
                resolved_stage.get("workflow_definition_key") or ""
            ),
            "event_ref": str(
                (trace_events[-1].get("event_id") if trace_events else "")
                or resolved_task.get("event_type")
                or ""
            ),
            "action_ref": str(resolved_task.get("action_key") or ""),
            "prior_results": context_pack.get("stage_history_summary") or [],
            "required_evidence": context_pack.get("required_evidence") or [],
            "missing_evidence": (
                (context_pack.get("evidence_summary") or {}).get("missing_raw")
                if isinstance(context_pack.get("evidence_summary"), dict)
                else []
            ) or [],
        }
        context_lines = [
            f"Context profile: {profile}",
            f"질문: {question}",
            f"업무 맥락: {business_context}",
            "",
            "BoI Wiki 근거:",
        ]
        for index, item in enumerate(items, start=1):
            context_lines.append(
                f"{index}. {item.get('title') or item.get('evidence_id')} — "
                f"{item.get('summary') or item.get('description') or item.get('text') or ''}"
            )
        if ontology_relationships:
            context_lines.extend(["", "검증된 Ontology 관계:"])
            for relation in ontology_relationships[:12]:
                context_lines.append(
                    f"- {relation['source_id']} — {relation['relation']} → {relation['target_id']} "
                    f"(근거: {', '.join(relation['source_refs'])})"
                )
        elif graph_results:
            context_lines.extend(["", "검증 가능한 provenance가 없어 문서 근거로 대체했습니다."])
        payload = {
            "question": question,
            "business_context": business_context,
            "context_profile": profile,
            "task_context": task_context,
            "save_mode": "private_draft" if request.get("save_mode") == "private_draft" else "preview",
            "title": str(request.get("title") or "Agent Playground 개인 초안").strip(),
            "trace_id": str(request.get("trace_id") or "").strip(),
            "context": "\n".join(context_lines).strip(),
            "document_ids": [item["ref"] for item in source_references if item["ref"]],
            "source_references": source_references,
            "ontology_relationships": ontology_relationships,
            "grounding_status": grounding_status,
            "permission_excluded_count": denied_count,
            "retrieval": {
                "strategy": search.get("retrieval_strategy") or "ontology_hybrid",
                "ontology_terms": search.get("ontology_terms") or [],
                "document_fallback": bool(items and not ontology_relationships),
            },
            "ontology": {
                "attempted": bool(graph_results or graph_errors),
                "grounded_relationship_count": len(ontology_relationships),
                "degraded": graph_errors,
                "document_fallback": bool(items and not ontology_relationships),
            },
            "context_pack": context_pack,
            "details": details,
            "provenance": {
                "document_refs": [item["ref"] for item in source_references if item["ref"]],
                "ontology_source_refs": list(
                    dict.fromkeys(
                        ref
                        for relation in ontology_relationships
                        for ref in relation["source_refs"]
                    )
                ),
            },
        }
        self._boi_payload_cache_key = cache_key
        self._boi_payload_cache = dict(payload)
        return payload

    async def load_knowledge(self) -> Data:
        return Data(data=await self._payload())

    async def build_agent_context(self) -> Message:
        payload = await self._payload()
        return Message(text=payload["context"], data=payload)

from __future__ import annotations

import json
import os
import re
import time
from typing import Any

import httpx

from lfx.custom import Component
from lfx.io import DataInput, MultilineInput, Output
from lfx.schema import Data
from lfx.utils.secrets import unwrap_secret_value


CODE_FENCE = re.compile(r"^```(?:json)?\s*|\s*```$", re.IGNORECASE)


class BoIUniversalSimulationMCPAgent(Component):
    display_name = "3. 업무 시뮬레이션 Agent"
    description = (
        "Wiki·Ontology 업무 맥락만 사용해 실제 시스템을 호출하지 않는 시뮬레이션을 만들고 "
        "근거와 provenance를 다음 단계에 그대로 전달합니다."
    )
    icon = "route"
    name = "BoIUniversalSimulationMCPAgent"

    inputs = [
        DataInput(
            name="agent_context",
            display_name="Wiki·Ontology 업무 맥락",
            required=True,
        ),
        MultilineInput(
            name="instructions",
            display_name="시뮬레이션 지시",
            value=(
                "제공된 업무 맥락과 근거 안에서만 처리 과정을 시뮬레이션하세요. "
                "실제 사내 시스템을 호출했다고 표현하지 말고, 근거가 부족하면 부족한 점을 "
                "명시하세요. source reference와 Ontology 식별자는 새로 만들거나 바꾸지 마세요."
            ),
            advanced=True,
        ),
    ]
    outputs = [
        Output(
            name="agent_result",
            display_name="근거가 보존된 시뮬레이션 결과",
            method="run_agent",
        )
    ]

    async def _variable(self, name: str) -> str:
        try:
            value = await self.get_variables(name, "value")
        except (TypeError, ValueError):
            value = ""
        return str(unwrap_secret_value(value) or "").strip()

    async def _configuration(self) -> tuple[str, str, str]:
        base_url = (
            await self._variable("BOI_LLM_BASE_URL")
            or os.getenv("BOI_LLM_BASE_URL", "")
        ).strip()
        model = (
            await self._variable("BOI_AGENT_EXAMPLE_MODEL")
            or os.getenv("BOI_AGENT_EXAMPLE_MODEL", "")
            or os.getenv("BOI_LLM_MODEL", "")
            or "google/gemma-4-26b-a4b-qat"
        ).strip()
        api_key = (
            await self._variable("BOI_LLM_API_KEY")
            or os.getenv("BOI_LLM_API_KEY", "")
        ).strip()
        if not base_url:
            raise ValueError(
                "BOI_LLM_BASE_URL이 없습니다. Langflow Credential/Global Variable로 모델 연결을 준비하세요."
            )
        return base_url.rstrip("/"), model, api_key

    @staticmethod
    def _chat_completions_url(base_url: str) -> str:
        return (
            f"{base_url}/chat/completions"
            if base_url.endswith("/v1")
            else f"{base_url}/v1/chat/completions"
        )

    @staticmethod
    def _decode_model_result(value: str) -> dict[str, Any]:
        text = CODE_FENCE.sub("", str(value or "").strip()).strip()
        try:
            decoded = json.loads(text)
        except json.JSONDecodeError as exc:
            raise ValueError(
                "Gemma가 Universal Simulation JSON 계약을 반환하지 않았습니다."
            ) from exc
        if not isinstance(decoded, dict):
            raise ValueError("Gemma Universal Simulation 응답은 JSON object여야 합니다.")
        required = (
            "summary",
            "proposed_handling",
            "expected_result",
            "limitations",
            "next_steps",
        )
        missing = [name for name in required if not decoded.get(name)]
        if missing:
            raise ValueError(
                "Gemma Universal Simulation 응답에 필수 필드가 없습니다: "
                + ", ".join(missing)
            )
        return decoded

    @staticmethod
    def _as_lines(value: Any) -> list[str]:
        if isinstance(value, list):
            return [str(item).strip() for item in value if str(item).strip()]
        if str(value or "").strip():
            return [str(value).strip()]
        return []

    @staticmethod
    def _coverage(
        payload: dict[str, Any],
        simulation: dict[str, Any],
        model_trace: dict[str, Any],
    ) -> dict[str, Any]:
        sources = [
            item
            for item in payload.get("source_references") or []
            if isinstance(item, dict)
        ]
        relations = [
            item
            for item in payload.get("ontology_relationships") or []
            if isinstance(item, dict)
        ]
        task_context = (
            payload.get("task_context")
            if isinstance(payload.get("task_context"), dict)
            else {}
        )
        profile = str(payload.get("context_profile") or "knowledge_lookup")
        checks = {
            "real_model_inference": bool(model_trace.get("real_inference")),
            "grounding_status": str(payload.get("grounding_status") or "")
            not in {"", "no_accessible_evidence"},
            "source_or_ontology_evidence": bool(sources or relations),
            "provenance": bool(payload.get("provenance")),
            "business_context": bool(
                str(payload.get("business_context") or "").strip()
                or task_context
            ),
            "simulation_contract": all(
                simulation.get(name)
                for name in ("summary", "proposed_handling", "expected_result")
            ),
            "limitations": bool(simulation.get("limitations")),
        }
        if profile in {"sop_task_execution", "task_execution"}:
            checks["resolved_task_context"] = bool(
                task_context.get("resolved_task_id")
                or task_context.get("task_ref")
            )
        required = list(checks)
        covered = [name for name, passed in checks.items() if passed]
        score = round(len(covered) / len(required), 2) if required else 0.0
        return {
            "profile": profile,
            "required": required,
            "covered": covered,
            "missing_context": [
                name for name, passed in checks.items() if not passed
            ],
            "coverage_score": score,
            "pass_threshold": 0.85,
            "passed": score >= 0.85,
        }

    @staticmethod
    def _markdown(
        simulation: dict[str, Any],
        coverage: dict[str, Any],
        source_references: list[dict[str, Any]],
        ontology_relationships: list[dict[str, Any]],
    ) -> str:
        lines = [
            "# SIMULATED · BoI Universal Simulation",
            "",
            "> 실제 사내 시스템을 호출하지 않은 근거 기반 미리보기입니다.",
            "",
            "## 처리 요약",
            str(simulation.get("summary") or ""),
            "",
            "## 시뮬레이션 처리",
        ]
        lines.extend(
            f"- {item}"
            for item in BoIUniversalSimulationMCPAgent._as_lines(
                simulation.get("proposed_handling")
            )
        )
        lines.extend(["", "## 예상 결과", str(simulation.get("expected_result") or "")])
        risks = BoIUniversalSimulationMCPAgent._as_lines(simulation.get("risks"))
        if risks:
            lines.extend(["", "## 위험·확인 사항", *[f"- {item}" for item in risks]])
        limitations = BoIUniversalSimulationMCPAgent._as_lines(
            simulation.get("limitations")
        )
        lines.extend(["", "## 부족한 근거와 제한", *[f"- {item}" for item in limitations]])
        next_steps = BoIUniversalSimulationMCPAgent._as_lines(
            simulation.get("next_steps")
        )
        lines.extend(["", "## 다음 단계", *[f"- {item}" for item in next_steps]])
        lines.extend(["", "## Wiki 근거"])
        lines.extend(
            f"- {item.get('title') or item.get('ref')} ({item.get('ref') or '-'})"
            for item in source_references[:8]
        )
        if not source_references:
            lines.append("- 현재 권한으로 확인된 문서 근거가 없습니다.")
        lines.extend(["", "## Ontology 관계"])
        lines.extend(
            (
                f"- {item.get('source_id')} — {item.get('relation')} → "
                f"{item.get('target_id')} (근거: {', '.join(item.get('source_refs') or [])})"
            )
            for item in ontology_relationships[:8]
        )
        if not ontology_relationships:
            lines.append("- 검증된 관계가 없어 문서 근거로 대체했습니다.")
        lines.extend(
            [
                "",
                "## Grounding coverage",
                (
                    f"- score={coverage.get('coverage_score')} / "
                    f"threshold={coverage.get('pass_threshold')}"
                ),
            ]
        )
        return "\n".join(lines).strip()

    async def run_agent(self) -> Data:
        payload = dict(getattr(self.agent_context, "data", {}) or {})
        base_url, model, api_key = await self._configuration()
        source_references = [
            item
            for item in payload.get("source_references") or []
            if isinstance(item, dict)
        ]
        ontology_relationships = [
            item
            for item in payload.get("ontology_relationships") or []
            if isinstance(item, dict)
        ]
        prompt_context = {
            "question": str(payload.get("question") or ""),
            "business_context": payload.get("business_context") or "",
            "context_profile": payload.get("context_profile")
            or "knowledge_lookup",
            "task_context": (
                payload.get("task_context")
                if isinstance(payload.get("task_context"), dict)
                else {}
            ),
            "grounding_status": payload.get("grounding_status")
            or "no_accessible_evidence",
            "wiki_context": payload.get("context") or "",
            "source_references": source_references,
            "ontology_relationships": ontology_relationships,
            "required_output": {
                "summary": "string",
                "proposed_handling": ["string"],
                "expected_result": "string",
                "risks": ["string"],
                "limitations": ["string"],
                "next_steps": ["string"],
            },
        }
        headers = {"Content-Type": "application/json"}
        if api_key and api_key not in {"not-needed", "none"}:
            headers["Authorization"] = f"Bearer {api_key}"
        request_body = {
            "model": model,
            "messages": [
                {
                    "role": "system",
                    "content": (
                        f"{str(self.instructions or '').strip()}\n\n"
                        "반드시 required_output과 같은 필드의 JSON object만 반환하세요."
                    ),
                },
                {
                    "role": "user",
                    "content": json.dumps(
                        prompt_context,
                        ensure_ascii=False,
                        default=str,
                    ),
                },
            ],
            "temperature": 0.1,
        }
        started = time.monotonic()
        async with httpx.AsyncClient(timeout=180) as client:
            response = await client.post(
                self._chat_completions_url(base_url),
                headers=headers,
                json=request_body,
            )
        response.raise_for_status()
        decoded = response.json()
        choices = decoded.get("choices") if isinstance(decoded, dict) else []
        first = choices[0] if isinstance(choices, list) and choices else {}
        message = first.get("message") if isinstance(first, dict) else {}
        simulation = self._decode_model_result(str((message or {}).get("content") or ""))
        model_trace = {
            "provider": "openai-compatible",
            "model": str(decoded.get("model") or model),
            "response_id": str(decoded.get("id") or ""),
            "latency_ms": round((time.monotonic() - started) * 1000, 1),
            "usage": (
                decoded.get("usage")
                if isinstance(decoded.get("usage"), dict)
                else {}
            ),
            "real_inference": True,
        }
        coverage = self._coverage(payload, simulation, model_trace)
        provenance = (
            dict(payload.get("provenance"))
            if isinstance(payload.get("provenance"), dict)
            else {}
        )
        provenance["model_agent"] = model_trace
        provenance["simulation_profile"] = "boi-universal-simulation-mcp-v1"
        answer = self._markdown(
            simulation,
            coverage,
            source_references,
            ontology_relationships,
        )
        return Data(
            data={
                "ok": True,
                "status": "simulated",
                "simulation": True,
                "simulation_label": "SIMULATED",
                "real_system_connected": False,
                "real_system_called": False,
                "simulation_notice": (
                    "실제 사내 시스템을 호출하지 않은 근거 기반 시뮬레이션입니다."
                ),
                "answer": answer,
                "simulation_result": simulation,
                "coverage_report": coverage,
                "limitations": self._as_lines(simulation.get("limitations")),
                "next_steps": self._as_lines(simulation.get("next_steps")),
                "question": payload.get("question") or "",
                "business_context": payload.get("business_context") or "",
                "save_mode": payload.get("save_mode") or "preview",
                "title": payload.get("title")
                or "Universal Simulation 개인 초안",
                "trace_id": payload.get("trace_id") or "",
                "context_profile": payload.get("context_profile")
                or "knowledge_lookup",
                "task_context": (
                    payload.get("task_context")
                    if isinstance(payload.get("task_context"), dict)
                    else {}
                ),
                "source_references": source_references,
                "ontology_relationships": ontology_relationships,
                "grounding_status": payload.get("grounding_status")
                or "no_accessible_evidence",
                "permission_excluded_count": int(
                    payload.get("permission_excluded_count") or 0
                ),
                "provenance": provenance,
                "agent_slot": self.__class__.__name__,
                "component_contract": "boi.agent-slot.v1",
                "executed_component_ids": [self.__class__.__name__],
                "model_trace": model_trace,
            }
        )

from __future__ import annotations

import base64
import json
import os
import re
from datetime import datetime, timezone
from typing import Any

from mcp import ClientSession
from mcp.client.streamable_http import streamablehttp_client

from lfx.custom import Component
from lfx.io import DataInput, DropdownInput, Output, StrInput
from lfx.schema import Data
from lfx.schema.message import Message
from lfx.utils.secrets import unwrap_secret_value


SECRET_VALUE = re.compile(r"(?:boi_(?:pat|run)_[A-Za-z0-9_-]+|sk-[A-Za-z0-9_-]{16,})")
MACHINE_RESULT_PREFIX = "BOI_RESULT_JSON_B64:"


def _decode_tool_result(result: Any) -> dict[str, Any]:
    if bool(
        getattr(result, "isError", False)
        or getattr(result, "is_error", False)
    ):
        detail = " ".join(
            str(getattr(item, "text", "") or "").strip()
            for item in getattr(result, "content", []) or []
            if str(getattr(item, "text", "") or "").strip()
        )
        raise RuntimeError(detail or "BoI Wiki MCP tool call failed")
    structured = getattr(result, "structuredContent", None) or getattr(result, "structured_content", None)
    if isinstance(structured, dict):
        return structured
    for item in getattr(result, "content", []) or []:
        text = getattr(item, "text", "")
        if not text:
            continue
        try:
            decoded = json.loads(text)
        except json.JSONDecodeError:
            continue
        if isinstance(decoded, dict):
            return decoded
    return {}


def _redact(value: Any) -> Any:
    if isinstance(value, str):
        return SECRET_VALUE.sub("[REDACTED]", value)
    if isinstance(value, dict):
        return {str(key): _redact(item) for key, item in value.items() if str(key).lower() not in {"api_key", "pat", "token", "service_token"}}
    if isinstance(value, list):
        return [_redact(item) for item in value]
    return value


class BoIWikiSave(Component):
    display_name = "Wiki에 지식 저장하기"
    description = "Agent 결과를 미리 보거나 현재 사용자의 private Wiki 초안으로만 저장합니다."
    icon = "save"
    name = "BoIWikiSave"

    inputs = [
        DataInput(name="agent_result", display_name="Agent 결과", required=True),
        StrInput(name="title", display_name="제목", value="Agent Playground 개인 초안"),
        DropdownInput(
            name="save_mode",
            display_name="저장 방식",
            options=["preview", "private_draft"],
            value="preview",
        ),
        DropdownInput(
            name="write_policy",
            display_name="초안 저장 권한",
            options=["owner_or_action", "action_token_required"],
            value="owner_or_action",
            advanced=True,
        ),
        StrInput(name="flow_id", display_name="Flow ID", value="boi-wiki-agent-loop", advanced=True),
    ]
    outputs = [
        Output(name="save_result", display_name="저장 결과", method="save"),
        Output(name="message", display_name="최종 출력", method="build_message"),
    ]

    def _request_variables(self) -> dict[str, Any]:
        try:
            graph = getattr(self, "graph", None)
            context = getattr(graph, "context", {}) if graph else {}
            request_variables = context.get("request_variables") if isinstance(context, dict) else {}
        except Exception:
            request_variables = {}
        return request_variables if isinstance(request_variables, dict) else {}

    async def _credential(self) -> str:
        run_token = str(self._request_variables().get("BOI_RUN_TOKEN") or "").strip()
        if run_token:
            return run_token
        try:
            value = await self.get_variables("BOI_WIKI_PAT", "value")
        except (TypeError, ValueError):
            value = ""
        raw_value = unwrap_secret_value(value)
        if str(raw_value or "").strip():
            return str(raw_value).strip()
        raise ValueError("BoI 지식 연결이 없습니다. Agent Playground 온보딩을 먼저 완료하세요.")

    async def _mcp_headers(self) -> dict[str, str]:
        headers = {"Authorization": f"Bearer {await self._credential()}"}
        variables = self._request_variables()
        for variable, header in {
            "BOI_ACTION_KEY": "X-BOI-Action-Key",
            "BOI_DEPLOYMENT_ID": "X-BOI-Deployment-ID",
            "BOI_ENDPOINT_ID": "X-BOI-Endpoint-ID",
            "BOI_PROJECT_ID": "X-BOI-Project-ID",
            "BOI_FLOW_ID": "X-BOI-Flow-ID",
            "BOI_TRACE_ID": "X-BOI-Trace-ID",
            "BOI_EXECUTION_ID": "X-BOI-Execution-ID",
        }.items():
            value = str(variables.get(variable) or "").strip()
            if value:
                headers[header] = value
        return headers

    async def _call(self, tool_name: str, arguments: dict[str, Any]) -> dict[str, Any]:
        endpoint = os.getenv("BOI_WIKI_MCP_URL", "http://boi-wiki-mcp:8200/mcp/v2")
        async with streamablehttp_client(
            endpoint,
            headers=await self._mcp_headers(),
        ) as (read_stream, write_stream, _):
            async with ClientSession(read_stream, write_stream) as session:
                await session.initialize()
                result = await session.call_tool(tool_name, arguments)
        return _decode_tool_result(result)

    def _agent_payload(self) -> dict[str, Any]:
        return _redact(dict(getattr(self.agent_result, "data", {}) or {}))

    @staticmethod
    def _machine_result(result: dict[str, Any]) -> str:
        """Encode the safe result contract in Chat Output for Langflow MCP clients.

        Langflow's project MCP transport currently serializes the final Message
        text, not Message.data.  Keep the human-readable Markdown unchanged and
        add a hidden, versioned payload that clients can decode without exposing
        credentials or relying on Markdown scraping.
        """

        contract = _redact(
            {
                "schema_version": "boi.universal-simulation.result.v1",
                "status": result.get("status") or "preview",
                "mode": result.get("mode") or "preview",
                "simulation": bool(result.get("simulation")),
                "simulation_label": result.get("simulation_label") or "",
                "simulation_notice": result.get("simulation_notice") or "",
                "real_system_called": bool(result.get("real_system_called")),
                "simulation_result": (
                    result.get("simulation_result")
                    if isinstance(result.get("simulation_result"), dict)
                    else {}
                ),
                "coverage_report": (
                    result.get("coverage_report")
                    if isinstance(result.get("coverage_report"), dict)
                    else {}
                ),
                "limitations": result.get("limitations") or [],
                "next_steps": result.get("next_steps") or [],
                "task_context": (
                    result.get("task_context")
                    if isinstance(result.get("task_context"), dict)
                    else {}
                ),
                "source_references": result.get("source_references") or [],
                "ontology_relationships": result.get("ontology_relationships")
                or [],
                "grounding_status": result.get("grounding_status") or "unknown",
                "permission_excluded_count": int(
                    result.get("permission_excluded_count") or 0
                ),
                "model_trace": (
                    result.get("model_trace")
                    if isinstance(result.get("model_trace"), dict)
                    else {}
                ),
                "draft_reference": result.get("draft_reference") or "",
                "wiki_url": result.get("wiki_url") or "",
                "production_changed": bool(result.get("production_changed")),
                "write_blocked": bool(result.get("write_blocked")),
                "write_blocked_reason": result.get("write_blocked_reason") or "",
                "provenance": (
                    result.get("provenance")
                    if isinstance(result.get("provenance"), dict)
                    else {}
                ),
            }
        )
        encoded = base64.b64encode(
            json.dumps(
                contract,
                ensure_ascii=False,
                separators=(",", ":"),
                sort_keys=True,
                default=str,
            ).encode("utf-8")
        ).decode("ascii")
        # Langflow 1.11 project MCP normalizes hidden Markdown metadata to the
        # space-delimited HTML comment form below.  Emit that canonical form
        # directly so /run and streamable MCP carry the same contract without
        # showing a long machine payload to first-time Canvas users.
        return f"<!-- {MACHINE_RESULT_PREFIX[:-1]} {encoded} -->"

    async def _result(self) -> dict[str, Any]:
        payload = self._agent_payload()
        request_variables = self._request_variables()
        has_run_token = bool(str(request_variables.get("BOI_RUN_TOKEN") or "").strip())
        write_policy = str(self.write_policy or "owner_or_action")
        cache_key = json.dumps(
            {
                "payload": payload,
                "write_policy": write_policy,
                "has_run_token": has_run_token,
            },
            ensure_ascii=False,
            sort_keys=True,
            default=str,
        )
        if (
            getattr(self, "_boi_save_cache_key", "") == cache_key
            and isinstance(getattr(self, "_boi_save_cache", None), dict)
        ):
            return dict(self._boi_save_cache)
        sources = [item for item in payload.get("source_references") or [] if isinstance(item, dict)]
        ontology_relationships = [
            item
            for item in payload.get("ontology_relationships") or []
            if isinstance(item, dict)
        ]
        requested_mode = "private_draft" if payload.get("save_mode") == "private_draft" else "preview"
        requested_title = str(payload.get("title") or self.title or "Agent Playground 개인 초안").strip()
        agent_provenance = (
            payload.get("provenance")
            if isinstance(payload.get("provenance"), dict)
            else {}
        )
        model_trace = (
            agent_provenance.get("model_agent")
            if isinstance(agent_provenance.get("model_agent"), dict)
            else payload.get("model_trace")
            if isinstance(payload.get("model_trace"), dict)
            else {}
        )
        trace = {
            "flow_id": str(self.flow_id or "boi-wiki-agent-loop"),
            "trace_id": str(payload.get("trace_id") or ""),
            "generated_at": datetime.now(timezone.utc).isoformat(),
            "source_references": sources,
            "ontology_relationships": ontology_relationships,
            "knowledge_provenance": agent_provenance,
            "task_context": payload.get("task_context") if isinstance(payload.get("task_context"), dict) else {},
            "agent_slot": payload.get("agent_slot") or "",
        }
        if model_trace:
            trace["model_agent"] = model_trace
        candidate = {
            "status": "preview",
            "mode": "preview",
            "title": requested_title,
            "answer": str(payload.get("answer") or ""),
            "source_references": sources,
            "ontology_relationships": ontology_relationships,
            "task_context": payload.get("task_context") if isinstance(payload.get("task_context"), dict) else {},
            "grounding_status": payload.get("grounding_status") or "unknown",
            "simulation": bool(payload.get("simulation")),
            "simulation_label": str(payload.get("simulation_label") or ""),
            "simulation_notice": str(payload.get("simulation_notice") or ""),
            "real_system_called": bool(payload.get("real_system_called")),
            "simulation_result": (
                payload.get("simulation_result")
                if isinstance(payload.get("simulation_result"), dict)
                else {}
            ),
            "coverage_report": (
                payload.get("coverage_report")
                if isinstance(payload.get("coverage_report"), dict)
                else {}
            ),
            "limitations": [
                str(item)
                for item in payload.get("limitations") or []
                if str(item)
            ],
            "next_steps": [
                str(item)
                for item in payload.get("next_steps") or []
                if str(item)
            ],
            "permission_excluded_count": int(
                payload.get("permission_excluded_count") or 0
            ),
            "model_trace": model_trace,
            "draft_reference": "",
            "wiki_url": "",
            "provenance": trace,
            "production_changed": False,
        }
        if requested_mode != "private_draft":
            self._boi_save_cache_key = cache_key
            self._boi_save_cache = dict(candidate)
            return candidate
        if write_policy == "action_token_required" and not has_run_token:
            blocked = {
                **candidate,
                "requested_mode": "private_draft",
                "write_blocked": True,
                "write_blocked_reason": "action_run_token_required",
            }
            self._boi_save_cache_key = cache_key
            self._boi_save_cache = dict(blocked)
            return blocked
        endpoint = os.getenv("BOI_WIKI_MCP_URL", "http://boi-wiki-mcp:8200/mcp/v2")
        async with streamablehttp_client(
            endpoint,
            headers=await self._mcp_headers(),
        ) as (read_stream, write_stream, _):
            async with ClientSession(read_stream, write_stream) as session:
                await session.initialize()

                async def call(tool_name: str, arguments: dict[str, Any]) -> dict[str, Any]:
                    return _decode_tool_result(await session.call_tool(tool_name, arguments))

                plan = await call(
                    "boi_plan",
                    {
                        "capability_id": "knowledge.draft",
                        "goal": f"{candidate['title']}\n\n{candidate['answer']}",
                        "page_ref": "/playground",
                        "input": {
                            "structured_private_draft": True,
                            "title": candidate["title"],
                            "body": candidate["answer"],
                            "summary": candidate["answer"][:500],
                            "source_refs": sources,
                            "ontology_relationships": ontology_relationships,
                            "task_context": candidate["task_context"],
                            "visibility": "private",
                            "provenance": trace,
                        },
                    },
                )
                plan_id = str(plan.get("plan_id") or plan.get("plan_ref") or "")
                if not plan_id:
                    for item in plan.get("offers") or []:
                        if isinstance(item, dict) and item.get("plan_id"):
                            plan_id = str(item["plan_id"])
                            break
                if not plan_id:
                    raise ValueError("BoI knowledge.draft plan did not return a plan_id")
                confirmed = await call(
                    "boi_confirm",
                    {
                        "plan_id": plan_id,
                        "reason": "Agent Playground에서 private_draft 저장 방식을 명시적으로 선택했습니다.",
                    },
                )
        draft_reference = str(
            confirmed.get("domain_ref")
            or confirmed.get("artifact_id")
            or confirmed.get("candidate_id")
            or plan.get("draft_reference")
            or plan_id
        )
        result = _redact(
            {
                **candidate,
                "status": "saved",
                "mode": "private_draft",
                "draft_reference": draft_reference,
                "wiki_url": str(
                    confirmed.get("wiki_url")
                    or confirmed.get("url")
                    or plan.get("wiki_url")
                    or ""
                ),
                "provenance": {**trace, "plan_id": plan_id},
                "production_changed": True,
                "confirmation": confirmed,
            }
        )
        self._boi_save_cache_key = cache_key
        self._boi_save_cache = dict(result)
        return result

    async def save(self) -> Data:
        return Data(data=await self._result())

    async def build_message(self) -> Message:
        result = await self._result()
        text = str(result.get("answer") or "")
        if result.get("mode") == "private_draft":
            text += f"\n\n개인 Wiki 초안: {result.get('draft_reference') or '저장됨'}"
        elif result.get("write_blocked"):
            text += (
                "\n\nMCP 미리보기만 수행했습니다. 개인 Wiki 초안 저장은 "
                "BoI Action 또는 Playground의 호출자 권한으로 실행하세요."
            )
        else:
            text += "\n\n미리보기만 수행했습니다. Wiki는 변경하지 않았습니다."
        text += f"\n\n{self._machine_result(result)}"
        return Message(text=text.strip(), data=result)
